Here is a complete, single-file Space Invaders game. It includes the HTML structure, CSS styling for the retro look, and the full JavaScript logic for movement, shooting, collision detection, and scoring.

Save this code as an `.html` file (e.g., `spaceinvaders.html`) and open it in any web browser.

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Space Invaders</title>
    <style>
        /* --- CSS STYLING --- */
        body {
            margin: 0;
            padding: 0;
            background-color: #000;
            color: #fff;
            font-family: 'Courier New', Courier, monospace;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            height: 100vh;
            overflow: hidden;
        }

        #gameContainer {
            position: relative;
            border: 2px solid #333;
            box-shadow: 0 0 20px rgba(0, 255, 0, 0.2);
        }

        canvas {
            display: block;
            background-color: #000;
        }

        #ui-layer {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            pointer-events: none; /* Let clicks pass through to canvas */
            display: flex;
            flex-direction: column;
        }

        .hud {
            display: flex;
            justify-content: space-between;
            padding: 10px 20px;
            font-size: 20px;
            text-transform: uppercase;
            z-index: 10;
        }

        .score { color: #0f0; }
        .lives { color: #f00; }

        #overlay {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            background: rgba(0, 0, 0, 0.7);
            z-index: 20;
            pointer-events: auto;
        }

        #overlay h1 {
            font-size: 48px;
            margin-bottom: 10px;
            text-shadow: 2px 2px #ff0000;
        }

        #overlay p {
            font-size: 18px;
            margin-bottom: 20px;
            color: #aaa;
        }

        .btn {
            background: #0f0;
            color: #000;
            border: none;
            padding: 10px 20px;
            font-size: 20px;
            cursor: pointer;
            font-family: inherit;
            text-transform: uppercase;
            transition: transform 0.1s;
        }

        .btn:hover {
            transform: scale(1.1);
        }

        .hidden {
            display: none !important;
        }

        /* Mobile Controls */
        #mobile-controls {
            margin-top: 10px;
            display: none; /* Hidden on desktop */
            gap: 10px;
            width: 100%;
            max-width: 600px;
        }

        .m-btn {
            background: #333;
            color: #fff;
            border: 1px solid #555;
            padding: 20px;
            font-size: 20px;
            cursor: pointer;
            user-select: none;
            -webkit-user-select: none;
            flex: 1;
            text-align: center;
        }

        @media (max-width: 700px) {
            #mobile-controls {
                display: flex;
            }
        }
    </style>
</head>
<body>

    <!-- Game Container -->
    <div id="gameContainer">
        <canvas id="gameCanvas"></canvas>

        <!-- HUD Overlay -->
        <div id="ui-layer">
            <div class="hud">
                <span id="scoreDisplay">Score: 0</span>
                <span id="levelDisplay">Level: 1</span>
                <span id="livesDisplay">Lives: 3</span>
            </div>
        </div>

        <!-- Start / Game Over Screen -->
        <div id="overlay">
            <h1 id="overlayTitle">SPACE INVADERS</h1>
            <p id="overlayMsg">Press SPACE or Click to Start</p>
            <button class="btn" id="startBtn">START GAME</button>
        </div>
    </div>

    <!-- Mobile Controls -->
    <div id="mobile-controls">
        <div class="m-btn" id="btnLeft">◀ LEFT</div>
        <div class="m-btn" id="btnShoot">▲ FIRE</div>
        <div class="m-btn" id="btnRight">RIGHT ▶</div>
    </div>

    <script>
        // --- JAVASCRIPT LOGIC ---

        const canvas = document.getElementById('gameCanvas');
        const ctx = canvas.getContext('2d');

        // UI Elements
        const overlay = document.getElementById('overlay');
        const overlayTitle = document.getElementById('overlayTitle');
        const overlayMsg = document.getElementById('overlayMsg');
        const startBtn = document.getElementById('startBtn');
        const scoreDisplay = document.getElementById('scoreDisplay');
        const levelDisplay = document.getElementById('levelDisplay');
        const livesDisplay = document.getElementById('livesDisplay');

        // Game Constants
        const CANVAS_WIDTH = 600;
        const CANVAS_HEIGHT = 600;
        const PLAYER_SPEED = 5;
        const BULLET_SPEED = 7;
        const ENEMY_ROWS = 5;
        const ENEMY_COLS = 10;
        const ENEMY_PADDING = 10;
        const ENEMY_SIZE = 30;
        const ENEMY_DROP_DISTANCE = 20;

        // Game State
        let gameState = 'IDLE'; // IDLE, PLAYING, GAMEOVER
        let score = 0;
        let lives = 3;
        let level = 1;
        let animationId;

        // Input Handling
        const keys = {};
        let touchLeft = false;
        let touchRight = false;
        let touchShoot = false;

        // Player Object
        const player = {
            x: 0,
            y: 0,
            width: 40,
            height: 20,
            color: '#0f0',
            dx: 0
        };

        // Arrays
        let bullets = [];
        let enemies = [];
        let enemyBullets = [];
        let particles = [];

        // --- INITIALIZATION ---
        function init() {
            canvas.width = CANVAS_WIDTH;
            canvas.height = CANVAS_HEIGHT;

            // Reset Player Position
            player.x = CANVAS_WIDTH / 2 - player.width / 2;
            player.y = CANVAS_HEIGHT - 50;

            // Reset Game Data
            score = 0;
            lives = 3;
            level = 1;
            bullets = [];
            enemyBullets = [];
            particles = [];

            createEnemies();
            updateHUD();
        }

        function createEnemies() {
            enemies = [];
            const startX = 50;
            const startY = 50;

            for (let r = 0; r < ENEMY_ROWS; r++) {
                for (let c = 0; c < ENEMY_COLS; c++) {
                    enemies.push({
                        x: startX + c * (ENEMY_SIZE + ENEMY_PADDING),
                        y: startY + r * (ENEMY_SIZE + ENEMY_PADDING),
                        width: ENEMY_SIZE,
                        height: ENEMY_SIZE,
                        alive: true,
                        color: getEnemyColor(r)
                    });
                }
            }
        }

        function getEnemyColor(row) {
            if (row === 0) return '#f00';
            if (row <= 2) return '#ff0';
            return '#0ff';
        }

        // --- INPUT HANDLING ---
        window.addEventListener('keydown', e => {
            keys[e.code] = true;
            if (['Space', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(e.code)) {
                e.preventDefault();
            }
            if (e.code === 'Space' && gameState !== 'PLAYING') {
                startGame();
            }
        });

        window.addEventListener('keyup', e => {
            keys[e.code] = false;
        });

        // Touch/Mobile Controls
        const btnLeft = document.getElementById('btnLeft');
        const btnRight = document.getElementById('btnRight');
        const btnShoot = document.getElementById('btnShoot');

        function addTouchListeners(element, actionStart, actionEnd) {
            element.addEventListener('touchstart', (e) => { e.preventDefault(); actionStart(); });
            element.addEventListener('touchend', (e) => { e.preventDefault(); actionEnd(); });
            element.addEventListener('mousedown', (e) => { e.preventDefault(); actionStart(); });
            element.addEventListener('mouseup', (e) => { e.preventDefault(); actionEnd(); });
        }

        addTouchListeners(btnLeft, () => touchLeft = true, () => touchLeft = false);
        addTouchListeners(btnRight, () => touchRight = true, () => touchRight = false);
        addTouchListeners(btnShoot, () => touchShoot = true, () => touchShoot = false);

        // --- GAME LOOP ---
        function startGame() {
            if (gameState === 'PLAYING') return;
            gameState = 'PLAYING';
            overlay.classList.add('hidden');
            init();
            loop();
        }

        function loop() {
            if (gameState !== 'PLAYING') return;

            update();
            draw();

            animationId = requestAnimationFrame(loop);
        }

        function stopGame(message) {
            gameState = 'GAMEOVER';
            cancelAnimationFrame(animationId);
            overlayTitle.innerText = "GAME OVER";
            overlayMsg.innerText = message;
            startBtn.innerText = "RETRY";
            overlay.classList.remove('hidden');
        }

        function winLevel() {
            level++;
            createEnemies();
            // Increase difficulty slightly
            updateHUD();
        }

        // --- UPDATE LOGIC ---
        function update() {
            // Player Movement
            let moveDir = 0;
            if (keys['ArrowLeft'] || keys['KeyA'] || touchLeft) moveDir -= 1;
            if (keys['ArrowRight'] || keys['KeyD'] || touchRight) moveDir += 1;

            player.x += moveDir * PLAYER_SPEED;

            // Clamp player position
            if (player.x < 0) player.x = 0;
            if (player.x + player.width > CANVAS_WIDTH) player.x = CANVAS_WIDTH - player.width;

            // Shooting
            if ((keys['Space'] || touchShoot) && bullets.length < 3) {
                // Simple cooldown via array length check
                bullets.push({
                    x: player.x + player.width / 2 - 2,
                    y: player.y,
                    width: 4,
                    height: 10,
                    dy: -BULLET_SPEED
                });
                keys['Space'] = false; // Prevent holding down for machine gun unless we want that
                // Actually, let's allow rapid fire but limit active bullets
                setTimeout(() => { keys['Space'] = false; }, 100); 
            }

            // Update Bullets
            for (let i = bullets.length - 1; i >= 0; i--) {
                bullets[i].y += bullets[i].dy;
                if (bullets[i].y < 0) bullets.splice(i, 1);
            }

            // Enemy Movement Logic
            let hitEdge = false;
            let enemySpeed = 1 + (level * 0.2);

            // Check bounds
            for (let e of enemies) {
                if (!e.alive) continue;
                if (e.x + e.width > CANVAS_WIDTH - 10 || e.x < 10) {
                    hitEdge = true;
                    break;
                }
            }

            for (let e of enemies) {
                if (!e.alive) continue;

                if (hitEdge) {
                    e.y += ENEMY_DROP_DISTANCE;
                } else {
                    e.x += enemySpeed;
                }
            }

            // Enemy Shooting
            if (Math.random() < 0.01 * level) { // Random chance to shoot
                const aliveEnemies = enemies.filter(e => e.alive);
                if (aliveEnemies.length > 0) {
                    const shooter = aliveEnemies[Math.floor(Math.random() * aliveEnemies.length)];
                    enemyBullets.push({
                        x: shooter.x + shooter.width/2,
                        y: shooter.y + shooter.height,
                        width: 3,
                        height: 10,
                        dy: 3 + (level * 0.5)
                    });
                }
            }

            // Update Enemy Bullets
            for (let i = enemyBullets.length - 1; i >= 0; i--) {
                enemyBullets[i].y += enemyBullets[i].dy;
                if (enemyBullets[i].y > CANVAS_HEIGHT) enemyBullets.splice(i, 1);
            }

            // Collision Detection: Player Bullet vs Enemies
            for (let i = bullets.length - 1; i >= 0; i--) {
                const b = bullets[i];
                for (let j = 0; j < enemies.length; j++) {
                    const e = enemies[j];
                    if (!e.alive) continue;

                    if (rectIntersect(b, e)) {
                        e.alive = false;
                        bullets.splice(i, 1);
                        score += 10;
                        createExplosion(e.x + e.width/2, e.y + e.height/2, e.color);
                        break;
                    }
                }
            }

            // Collision Detection: Enemy Bullet vs Player
            for (let i = enemyBullets.length - 1; i >= 0; i--) {
                const b = enemyBullets[i];
                if (rectIntersect(b, player)) {
                    enemyBullets.splice(i, 1);
                    lives--;
                    createExplosion(player.x + player.width/2, player.y + player.height/2, '#0f0');
                    if (lives <= 0) {
                        stopGame("Final Score: " + score);
                        return;
                    }
                }
            }

            // Check if enemies reached bottom
            for (let e of enemies) {
                if (e.alive && e.y + e.height > player.y) {
                    stopGame("Invaders breached defenses! Score: " + score);
                    return;
                }
            }

            // Check Win Condition
            if (enemies.every(e => !e.alive)) {
                winLevel();
            }

            // Update Particles
            for (let i = particles.length - 1; i >= 0; i--) {
                particles[i].life--;
                particles[i].x += particles[i].dx;
                particles[i].y += particles[i].dy;
                if (particles[i].life <= 0) particles.splice(i, 1);
            }

            updateHUD();
        }

        function rectIntersect(a, b) {
            return !(a.x + a.width < b.x ||
                     a.x > b.x + b.width ||
                     a.y + a.height < b.y ||
                     a.y > b.y + b.height);
        }

        function createExplosion(x, y, color) {
            for (let i = 0; i < 10; i++) {
                particles.push({
                    x: x,
                    y: y,
                    dx: (Math.random() - 0.5) * 5,
                    dy: (Math.random() - 0.5) * 5,
                    life: 20 + Math.random() * 10,
                    color: color
                });
            }
        }

        function updateHUD() {
            scoreDisplay.innerText = `Score: ${score}`;
            levelDisplay.innerText = `Level: ${level}`;
            livesDisplay.innerText = `Lives: ${lives}`;
        }

        // --- DRAWING LOGIC ---
        function draw() {
            // Clear Canvas
            ctx.fillStyle = '#000';
            ctx.fillRect(0, 0, canvas.width, canvas.height);

            // Draw Stars (Background effect)
            ctx.fillStyle = '#333';
            for(let i=0; i<50; i++) {
                // Deterministic stars based on index so they don't flicker
                ctx.fillRect((i*137)%CANVAS_WIDTH, (i*97)%CANVAS_HEIGHT, 1, 1);
            }

            // Draw Player
            ctx.fillStyle = player.color;
            // Draw simple ship shape
            ctx.beginPath();
            ctx.moveTo(player.x + player.width/2, player.y);
            ctx.lineTo(player.x + player.width, player.y + player.height);
            ctx.lineTo(player.x, player.y + player.height);
            ctx.closePath();
            ctx.fill();

            // Draw Bullets
            ctx.fillStyle = '#fff';
            for (let b of bullets) {
                ctx.fillRect(b.x, b.y, b.width, b.height);
            }

            // Draw Enemy Bullets
            ctx.fillStyle = '#f00';
            for (let b of enemyBullets) {
                ctx.fillRect(b.x, b.y, b.width, b.height);
            }

            // Draw Enemies
            for (let e of enemies) {
                if (!e.alive) continue;
                ctx.fillStyle = e.color;
                // Draw simple invader shape
                ctx.fillRect(e.x, e.y, e.width, e.height);
                // Eyes
                ctx.fillStyle = '#000';
                ctx.fillRect(e.x + 5, e.y + 5, 5, 5);
                ctx.fillRect(e.x + e.width - 10, e.y + 5, 5, 5);
            }

            // Draw Particles
            for (let p of particles) {
                ctx.globalAlpha = p.life / 30;
                ctx.fillStyle = p.color;
                ctx.fillRect(p.x, p.y, 2, 2);
            }
            ctx.globalAlpha = 1.0;
        }

        // --- START BUTTON ---
        startBtn.addEventListener('click', startGame);

        // Initial setup call
        init();
        // Draw static screen initially
        draw();
    </script>
</body>
</html>
```

### How to play:
1.  **Copy** the code above.
2.  **Paste** it into a text editor (Notepad, TextEdit, VS Code).
3.  **Save** the file with an `.html` extension (e.g., `invaders.html`).
4.  **Open** the file in your web browser (Chrome, Firefox, Edge, Safari).

### Features included:
*   **Classic Gameplay:** Move left/right, shoot invaders.
*   **Levels:** The game gets harder as you clear waves (enemies move faster and shoot more often).
*   **Visual Effects:** Particle explosions when enemies die.
*   **Mobile Support:** On smaller screens, touch buttons appear at the bottom.
*   **Collision Detection:** Bullets hitting enemies and enemies hitting the player.
*   **No External Dependencies:** Everything runs inside one file without needing internet access.
